"""
eSuite Client fuer die Konvertierung von IDs und Referenzen ueber die eSuite Resources-API.
"""

import logging
from typing import Any

from ..config_service import get_esuite_api_config
from ..utils.http_utils import retry_request

logger = logging.getLogger(__name__)


def _get_environment_config(environment: str) -> tuple[dict[str, str], str]:
    """Gibt Header und Resthost fuer eine eSuite-Umgebung zurueck."""
    config = get_esuite_api_config(environment)
    return config.headers, config.resthost


def convert_id(environment: str, id: str, reference_type: str) -> str:
    """Konvertiert eine ID in eine Referenz ueber die eSuite Resources-API.

    Args:
        environment: Die Zielumgebung ("PROD" oder "UAT").
        id: Die zu konvertierende ID, z. B. SubscriptionID.
        reference_type: "S" fuer SubscriptionID oder "A" fuer AccountID.

    Returns:
        Die konvertierte Referenz als String.

    Raises:
        RuntimeError: Wenn keine Antwort von der API kommt.
        ValueError: Wenn die Umgebung unbekannt ist.
    """
    headers, resthost = _get_environment_config(environment)
    url = resthost + "resources"
    params = {"referenceType": reference_type, "id": id}

    try:
        response = retry_request("POST", url, json=params, headers=headers, verify=False)
        if response is None:
            raise RuntimeError(f"Keine Antwort beim Konvertieren von ID {id}")
        return str(response.text)
    except (RuntimeError, ValueError) as exc:
        logger.error("Error converting id %s: %s", id, exc, exc_info=True)
        raise


def _extract_resource_id(data: Any, reference: str) -> str | int:
    """Extrahiert die Resource-ID aus einer Graph/eSuite-Response."""
    if isinstance(data, dict):
        resource_id = data.get("id")
        if isinstance(resource_id, str | int):
            return resource_id
        raise RuntimeError(f"Kein gueltiges 'id'-Feld in Antwort fuer Reference {reference}")

    if isinstance(data, str | int):
        return data

    raise RuntimeError(f"Ungueltige Antwort fuer Reference {reference}: {type(data).__name__}")


def convert_reference_to_id(environment: str, reference: str) -> str | int:
    """Konvertiert eine Subscriptionreference in die zugehoerige SubscriptionID.

    Args:
        environment: Die Zielumgebung ("PROD" oder "UAT").
        reference: Die zu konvertierende Subscriptionreference.

    Returns:
        Die konvertierte SubscriptionID.

    Raises:
        RuntimeError: Wenn keine Antwort oder ein Fehler von der API kommt.
        ValueError: Wenn die Umgebung unbekannt ist.
    """
    headers, resthost = _get_environment_config(environment)
    url = resthost + "resources/" + reference
    response = retry_request("GET", url, headers=headers, verify=False)
    if response is None or response.status_code != 200:
        status = response.status_code if response else "No Response"
        raise RuntimeError(f"Fehler beim Konvertieren von Reference {reference}: status {status}")

    try:
        return _extract_resource_id(response.json(), reference)
    except ValueError:
        response_text = str(response.text).strip()
        if not response_text:
            raise RuntimeError(f"Leere Antwort beim Konvertieren von Reference {reference}") from None
        return response_text
